import pickle
from contextlib import asynccontextmanager
from typing import List

from fastapi import FastAPI
from pydantic import BaseModel, conlist

MODEL_PATH = '/app/models/best_model.pkl'
MODEL_NAME = 'random_forest'
state = {'model': None}


@asynccontextmanager
async def lifespan(app):
    with open(MODEL_PATH, 'rb') as f:
        state['model'] = pickle.load(f)
    yield


app = FastAPI(title='California Housing Price API', lifespan=lifespan)


class PredictRequest(BaseModel):
    features: conlist(float, min_length=8, max_length=8)


class BatchRequest(BaseModel):
    features_list: List[conlist(float, min_length=8, max_length=8)]


@app.post('/predict')
def predict(req: PredictRequest):
    pred = state['model'].predict([req.features])[0]
    return {'prediction': float(pred), 'model_name': MODEL_NAME}


@app.get('/health')
def health():
    return {'status': 'healthy', 'model_loaded': state['model'] is not None}


@app.get('/model-info')
def model_info():
    return {
        'model_name': MODEL_NAME,
        'model_type': type(state['model']).__name__,
        'features_count': 8,
    }


@app.post('/predict-batch')
def predict_batch(req: BatchRequest):
    preds = state['model'].predict(req.features_list)
    return {
        'predictions': [float(p) for p in preds],
        'model_name': MODEL_NAME,
        'count': len(req.features_list),
    }
EOF
